import json
import re
from docx import Document
from pathlib import Path

TEMPLATE = Path('/root/offer_letter_template.docx')
DATA = Path('/root/employee_data.json')
OUTPUT = Path('/root/offer_letter_filled.docx')

with DATA.open() as f:
    data = json.load(f)

# Normalize to string for replacements
str_data = {k: ('' if v is None else str(v)) for k, v in data.items()}

should_include_relocation = str_data.get('RELOCATION_PACKAGE', '').strip().lower() == 'yes'

start_marker = '{{IF_RELOCATION}}'
end_marker = '{{END_IF_RELOCATION}}'


def set_paragraph_text(para, text):
    # Preserve formatting by keeping first run
    if para.runs:
        para.runs[0].text = text
        for run in para.runs[1:]:
            run.text = ''
    else:
        para.add_run(text)


def remove_between(text, start_marker, end_marker):
    while True:
        start = text.find(start_marker)
        end = text.find(end_marker)
        if start == -1 or end == -1 or end < start:
            break
        text = text[:start] + text[end + len(end_marker):]
    return text


def handle_conditionals_in_paragraphs(paragraphs, should_include):
    in_block = False
    for para in paragraphs:
        text = para.text
        if not in_block:
            if start_marker in text:
                if end_marker in text:
                    if should_include:
                        new_text = text.replace(start_marker, '').replace(end_marker, '')
                    else:
                        new_text = remove_between(text, start_marker, end_marker)
                    set_paragraph_text(para, new_text)
                else:
                    in_block = True
                    if should_include:
                        new_text = text.replace(start_marker, '')
                    else:
                        idx = text.find(start_marker)
                        new_text = text[:idx]
                    set_paragraph_text(para, new_text)
        else:
            if end_marker in text:
                if should_include:
                    new_text = text.replace(end_marker, '')
                else:
                    idx = text.find(end_marker) + len(end_marker)
                    new_text = text[idx:]
                set_paragraph_text(para, new_text)
                in_block = False
            else:
                if not should_include:
                    set_paragraph_text(para, '')


def replace_placeholders_in_paragraph(para):
    text = para.text
    if '{{' not in text or '}}' not in text:
        return
    pattern = r'\{\{([A-Z0-9_]+)\}\}'
    matches = re.findall(pattern, text)
    if not matches:
        return
    new_text = text
    for key in matches:
        placeholder = '{{' + key + '}}'
        if key in str_data:
            new_text = new_text.replace(placeholder, str_data[key])
    if new_text != text:
        set_paragraph_text(para, new_text)


def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            # conditionals in cell paragraphs
            handle_conditionals_in_paragraphs(cell.paragraphs, should_include_relocation)
            for para in cell.paragraphs:
                replace_placeholders_in_paragraph(para)
            for nested in cell.tables:
                process_table(nested)


def process_container(paragraphs, tables):
    handle_conditionals_in_paragraphs(paragraphs, should_include_relocation)
    for para in paragraphs:
        replace_placeholders_in_paragraph(para)
    for table in tables:
        process_table(table)


doc = Document(str(TEMPLATE))

# Main document
process_container(doc.paragraphs, doc.tables)

# Headers/footers
for section in doc.sections:
    process_container(section.header.paragraphs, section.header.tables)
    process_container(section.footer.paragraphs, section.footer.tables)

# Also process first_page_header/footer or even/odd if present
for section in doc.sections:
    for hf in [section.first_page_header, section.first_page_footer, section.even_page_header, section.even_page_footer]:
        process_container(hf.paragraphs, hf.tables)

# Save
OUTPUT.parent.mkdir(parents=True, exist_ok=True)
doc.save(str(OUTPUT))

print(f"Wrote {OUTPUT}")
