from docx import Document
from pathlib import Path

path = Path('/root/offer_letter_filled.docx')
doc = Document(str(path))
remaining = []

def scan_paragraphs(paragraphs):
    for p in paragraphs:
        if '{{' in p.text or '}}' in p.text:
            remaining.append(p.text)

scan_paragraphs(doc.paragraphs)
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            scan_paragraphs(cell.paragraphs)
            for nested in cell.tables:
                for nrow in nested.rows:
                    for ncell in nrow.cells:
                        scan_paragraphs(ncell.paragraphs)

for section in doc.sections:
    scan_paragraphs(section.header.paragraphs)
    scan_paragraphs(section.footer.paragraphs)
    scan_paragraphs(section.first_page_header.paragraphs)
    scan_paragraphs(section.first_page_footer.paragraphs)
    scan_paragraphs(section.even_page_header.paragraphs)
    scan_paragraphs(section.even_page_footer.paragraphs)

print('Remaining placeholders:', len(remaining))
for t in remaining[:10]:
    print('-', t)
